INSERT INTO repo_kcrs (kcr_id, name, domain, concept_category, concept_type, definition, scope, core_principles, semantic_description, keywords_synonyms, status) VALUES ('KCR_000101', 'Free/forced convection', 'Engineering & Technology', 'Heat and Mass Transfer', 'Technical Concept', 'Heat transfer between a surface and moving fluid driven respectively by buoyancy or by externally imposed fluid motion.', 'Natural/free convection, forced convection, boundary layers, dimensionless correlations and heat-transfer coefficients.', 'Convection; buoyancy; forced flow; boundary layers.', 'Free convection is driven by density differences caused by temperature variations, while forced convection is driven by fans, pumps or other imposed motion.', 'Boundary layers; Reynolds number; heat transfer', 'Active'), ('KCR_000102', 'Blackbody radiation', 'Engineering & Technology', 'Heat and Mass Transfer', 'Technical Concept', 'Thermal radiation idealization for a surface that absorbs all incident radiation and emits the maximum possible radiation at a given temperature.', 'Blackbody emissive power, Stefan-Boltzmann law, spectral distribution and radiative exchange assumptions.', 'Thermal radiation; emissive power; temperature dependence.', 'A blackbody is an ideal radiative surface with emissivity of one. Its total emissive power follows the Stefan-Boltzmann relation.', 'Thermal radiation; Stefan-Boltzmann law; emissive power; temperature dependence; Heat and Mass Transfer', 'Active'), ('KCR_000103', 'Log Mean Temperature Difference (LMTD)', 'Engineering & Technology', 'Heat and Mass Transfer; Fluid Flow and Heat Transfer', 'Technical Concept', 'Log-mean temperature difference, a mean temperature-driving-force measure used in heat-exchanger analysis when the temperature difference varies along the exchanger.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for LMTD.', 'LMTD converts a spatially varying temperature difference into an effective mean driving force for specified heat-exchanger arrangements.', 'Heat exchangers; convection; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for LMTD', 'Active'), ('KCR_000104', 'Mass diffusion and transfer coefficients', 'Engineering & Technology', 'Heat and Mass Transfer', 'Technical Concept', 'Transport of chemical species caused by concentration gradients and the coefficients used to relate mass-transfer flux to a driving concentration difference.', 'Fickian diffusion, concentration gradients, molecular diffusivity, convective mass transfer and dimensionless correlations.', 'Species conservation; diffusion; convection; mass-transfer resistance.', 'Diffusive mass flux is related to concentration gradients through Fick''s law under its applicable assumptions; mass-transfer coefficients characterize convective transfer across interfaces or boundary layers.', 'Fick''s law; mass transfer; boundary layers', 'Active'), ('KCR_000105', 'Flywheels', 'Engineering & Technology', 'Dynamics of Machines', 'Technical Concept', 'Rotating mechanical energy-storage elements that reduce cyclic speed fluctuations by storing and releasing kinetic energy.', 'Energy fluctuation, moment of inertia, coefficient of speed fluctuation and angular velocity.', 'Energy storage; inertia; speed regulation.', 'A flywheel stores kinetic energy proportional to rotational inertia and the square of angular speed and smooths periodic speed variations.', 'Rotational dynamics; energy storage; inertia; speed regulation; Dynamics of Machines', 'Active'), ('KCR_000106', 'Static and dynamic balancing', 'Engineering & Technology', 'Dynamics of Machines', 'Technical Concept', 'Procedures for reducing unbalanced forces and moments in rotating or reciprocating machinery.', 'Mass distribution, centrifugal forces, static balance, couple balance, correction planes and balancing procedures.', 'Force balance; moment balance; vibration reduction.', 'Static balancing addresses resultant unbalanced force, while dynamic balancing also accounts for the resultant unbalanced couple and generally requires correction in multiple planes.', 'Rotating machinery; vibration; Force balance; moment balance; vibration reduction; Dynamics of Machines', 'Active'), ('KCR_000107', 'Natural frequency', 'Engineering & Technology', 'Dynamics of Machines', 'Technical Concept', 'A characteristic frequency at which a system can oscillate freely after a disturbance in the absence of sustained external excitation and damping effects.', 'Single/multi-degree systems, stiffness, mass, damping influence and mode shapes.', 'Inertia; stiffness; modal behaviour.', 'Natural frequencies arise from the system''s mass and stiffness properties; damping modifies the observed damped frequency and response.', 'Free vibration; modal analysis; Inertia; stiffness; modal behaviour; Dynamics of Machines', 'Active'), ('KCR_000108', 'Resonance', 'Engineering & Technology', 'Dynamics of Machines', 'Technical Concept', 'A condition in which forced vibration response becomes large when excitation frequency approaches an appropriate natural frequency of the system.', 'Frequency response, damping, natural frequency, amplitude and phase behaviour.', 'Dynamic amplification; frequency matching; damping.', 'Resonance results from strong dynamic response near a system''s natural frequency. Damping limits peak response, but the precise resonance condition depends on the response measure.', 'Natural frequency; forced vibration; Dynamic amplification; frequency matching; damping; Dynamics of Machines', 'Active'), ('KCR_000109', 'Governor and gyroscope principles', 'Engineering & Technology', 'Dynamics of Machines', 'Technical Concept', 'Rotational-mechanics principles represented by governors for speed regulation and gyroscopes for angular-momentum-based orientation and reaction effects.', 'Governor equilibrium/speed regulation; gyroscopic moment, precession and angular momentum.', 'Feedback/regulation; angular momentum; dynamic stability.', 'A governor mechanically senses speed-related conditions to regulate engine input, while a gyroscope exhibits orientation and reaction behaviour arising from angular momentum and precession.', 'Rotational dynamics; angular momentum; Feedback/regulation; dynamic stability; Dynamics of Machines', 'Active'), ('KCR_000110', 'Sand casting', 'Engineering & Technology', 'Manufacturing Processes', 'Method / Process', 'A metal casting process in which molten metal is poured into a mould cavity formed in compacted sand.', 'Pattern, moulding sand, gating/riser system, solidification, defects and post-casting finishing.', 'Material shaping; solidification; resource use; process quality.', 'Sand casting produces near-net-shape components by solidifying molten metal in a disposable sand mould. Quality depends on mould design, metal flow and solidification control.', 'Casting; solidification; Material shaping; resource use; process quality; Manufacturing Processes', 'Active'), ('KCR_000111', 'Forging', 'Engineering & Technology', 'Manufacturing Processes', 'Method / Process', 'A manufacturing process that plastically deforms metal using compressive forces to produce a desired shape and properties.', 'Open/closed-die forging, temperature, deformation, grain flow, tooling and defects.', 'Plastic deformation; material integrity; grain flow; energy input.', 'Forging shapes material through controlled plastic deformation and can produce favourable grain flow and mechanical properties when process conditions are appropriate.', 'Metal forming; plastic deformation; material integrity; grain flow; energy input; Manufacturing Processes', 'Active'), ('KCR_000112', 'Arc welding', 'Engineering & Technology', 'Manufacturing Processes', 'Method / Process', 'A fusion welding process in which an electric arc supplies heat to melt and join materials, with or without filler metal.', 'Arc generation, electrodes, shielding, heat input, joint preparation, weld defects and safety.', 'Fusion; heat transfer; metallurgical control; joint integrity.', 'Arc welding joins materials by localized arc heating and solidification. Electrical parameters, shielding and thermal history influence weld quality.', 'Welding; heat input; Fusion; heat transfer; metallurgical control; joint integrity', 'Active'), ('KCR_000113', 'Lathe operations', 'Engineering & Technology', 'Manufacturing Processes', 'Method / Process', 'Material-removal operations performed on a lathe in which a workpiece rotates while a cutting tool removes material.', 'Turning, facing, tapering, threading, boring, cutting speed, feed, depth of cut and tool geometry.', 'Material removal; geometric accuracy; cutting mechanics; productivity.', 'Lathe operations generate cylindrical or related surfaces by controlled relative motion between rotating work and cutting tool.', 'Machining; cutting parameters; Material removal; geometric accuracy; cutting mechanics; productivity', 'Active'), ('KCR_000114', 'Electrical discharge machining', 'Engineering & Technology', 'Manufacturing Processes', 'Technical Concept', 'A non-contact machining process that removes electrically conductive workpiece material through controlled electrical discharges in a dielectric medium.', 'Electrode/workpiece gap, spark energy, dielectric, material removal rate, surface finish and tool wear.', 'Localized energy transfer; material removal; process control.', 'EDM removes conductive material through repeated electrical discharges. It is useful for hard or complex conductive materials but involves electrode wear and energy consumption.', 'Non-traditional machining; electrical discharge; Localized energy transfer; material removal; process control; Manufacturing Processes', 'Active'), ('KCR_000115', 'Von Mises', 'Engineering & Technology', 'Design of Machine Elements', 'Technical Concept', 'The von Mises yield criterion predicts yielding of ductile isotropic materials from the distortion-energy component of the stress state.', 'Equivalent von Mises stress, multiaxial stress states, yield strength comparison and ductile-metal applicability.', 'Distortion energy; yielding; multiaxial stress.', 'The von Mises criterion compares an equivalent scalar stress with the material''s yield strength and is widely used for ductile isotropic metals under multiaxial loading.', 'Yield criteria; stress invariants; Distortion energy; yielding; multiaxial stress; Design of Machine Elements', 'Active'), ('KCR_000116', 'Goodman diagram', 'Engineering & Technology', 'Design of Machine Elements', 'Principle / Criterion', 'A fatigue-design diagram relating alternating stress and mean stress to an endurance-strength criterion, commonly using a linear Goodman relation.', 'Mean stress, alternating stress, endurance strength, ultimate strength and safety factors.', 'Fatigue; mean-stress effect; safety factor.', 'The Goodman relation provides a conservative linear approximation for the effect of mean stress on fatigue strength and is used in high-cycle fatigue design.', 'Fatigue failure; S-N behaviour; Fatigue; mean-stress effect; safety factor; Design of Machine Elements', 'Active'), ('KCR_000117', 'Shaft and key design', 'Engineering & Technology', 'Design of Machine Elements', 'Method / Process', 'Design of rotating shafts and keys to transmit torque while satisfying strength, stiffness, fatigue and connection requirements.', 'Torsional/bending stresses, diameter, key dimensions, stress concentrations, deflection and torque transmission.', 'Strength; stiffness; fatigue; torque transmission.', 'Shaft design considers combined loading, torsional strength, bending, fatigue and deformation. Keys transmit torque between a shaft and hub while requiring checks against shear and bearing failure.', 'Torsion; fatigue; machine elements', 'Active'), ('KCR_000118', 'Journal bearings', 'Engineering & Technology', 'Design of Machine Elements', 'Technical Concept', 'Bearings that support a rotating shaft through sliding contact, commonly separated by a lubricating film under hydrodynamic or related regimes.', 'Bearing pressure, viscosity, clearance, Sommerfeld-type parameters, lubrication regime, friction and heat generation.', 'Lubrication; friction reduction; load capacity; thermal management.', 'Journal-bearing performance depends on shaft speed, load, clearance, lubricant properties and geometry. Hydrodynamic lubrication can sustain load through pressure generated in the lubricant film.', 'Tribology; lubrication; friction reduction; load capacity; thermal management; Design of Machine Elements', 'Active'), ('KCR_000119', 'Gear design fundamentals', 'Engineering & Technology', 'Design of Machine Elements', 'Method / Process', 'Principles used to select and proportion gears for transmitting motion and torque while satisfying strength, wear, accuracy and service-life requirements.', 'Gear geometry, module/diametral pitch, tooth forces, bending/contact stress, ratios and failure modes.', 'Power transmission; strength; wear; reliability; geometry.', 'Gear design balances kinematic requirements with tooth bending and contact strength, wear, manufacturability and service-life considerations.', 'Gear trains; fatigue; contact stress', 'Active'), ('KCR_000120', 'Laplace transforms', 'Engineering & Technology', 'Control Systems Engineering', 'Method / Process', 'An integral transform that maps suitable time-domain functions to an algebraic function of a complex variable and is widely used to analyze linear dynamic systems.', 'Transform definition, properties, inverse transform, poles/zeros and differential-equation solution.', 'Linear systems; superposition; transform-domain analysis.', 'Laplace transforms convert differential equations and convolution relationships into algebraic forms under stated existence and initial-condition assumptions.', 'Differential equations; transfer functions; Linear systems; superposition; transform-domain analysis; Control Systems Engineering', 'Active'), ('KCR_000121', 'Time-domain response', 'Engineering & Technology', 'Control Systems Engineering', 'Technical Concept', 'The temporal output behaviour of a dynamic system following an input, disturbance or initial condition.', 'Transient and steady-state response, rise time, settling time, overshoot, damping and natural frequency.', 'Stability; transient performance; steady-state accuracy.', 'Time-domain response metrics quantify how a dynamic system approaches its final or steady behaviour and reveal the effects of poles, damping and system parameters.', 'Dynamic systems; transfer functions; Stability; transient performance; steady-state accuracy; Control Systems Engineering', 'Active'), ('KCR_000122', 'Routh-Hurwitz and Nyquist criteria', 'Engineering & Technology', 'Control Systems Engineering', 'Technical Concept', 'Frequency- or polynomial-domain stability-analysis methods used to determine whether a feedback system has unstable poles or encirclements associated with closed-loop instability.', 'Routh array, characteristic polynomial, Nyquist plot, encirclement criterion and open-loop/closed-loop relationships.', 'Stability; pole location; feedback; robustness.', 'Routh-Hurwitz assesses polynomial stability without explicitly solving for roots. Nyquist uses the frequency response and encirclement criterion to infer closed-loop stability under its assumptions.', 'Characteristic equation; frequency response; Stability; pole location; feedback; robustness', 'Active'), ('KCR_000123', 'Bode plot', 'Engineering & Technology', 'Control Systems Engineering', 'Technical Concept', 'A logarithmic magnitude-and-phase representation of a system''s frequency response as a function of frequency.', 'Magnitude in decibels, phase, corner frequencies, asymptotic construction and gain/phase margins.', 'Frequency response; stability margins; bandwidth.', 'Bode plots expose frequency-dependent gain and phase and support assessment of bandwidth, stability margins and compensator effects.', 'Frequency response; transfer functions; stability margins; bandwidth; Control Systems Engineering', 'Active'), ('KCR_000124', 'PID control', 'Engineering & Technology', 'Control Systems Engineering; Mechatronics', 'Method / Process', 'Feedback control using proportional, integral, and derivative actions to regulate a process variable based on the control error.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for PID control.', 'PID control combines proportional response, integral accumulation and derivative prediction to shape closed-loop performance. Practical implementations require attention to saturation, noise and tuning.', 'Feedback control; controller tuning; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for PID control', 'Active'), ('KCR_000125', 'agents and environments', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'agents and environments in Artificial Intelligence concerns the interaction between an intelligent agent and the environment through percepts, actions, state transitions, and performance measures.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of agents and environments within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'Core considerations include the defining characteristics of agents and environments, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'agents and environments in Artificial Intelligence concerns the interaction between an intelligent agent and the environment through percepts, actions, state transitions, and performance measures. Within Intelligent Agents, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of agents and environments within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of agents and environments, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'agents and environments; Core considerations include the defining characteristics of agents and environments, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000126', 'rational action', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'rational action in Artificial Intelligence concerns the selection of actions that maximize expected performance given the agent''s percept history, knowledge, and available actions.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of rational action within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'Core considerations include the defining characteristics of rational action, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'rational action in Artificial Intelligence concerns the selection of actions that maximize expected performance given the agent''s percept history, knowledge, and available actions. Within Intelligent Agents, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of rational action within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of rational action, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'rational action; Core considerations include the defining characteristics of rational action, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000127', 'agent architectures', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'agent architectures in Artificial Intelligence concerns the computational organization of sensing, internal state, reasoning, learning, and action used to implement an intelligent agent.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of agent architectures within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'Core considerations include the defining characteristics of agent architectures, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'agent architectures in Artificial Intelligence concerns the computational organization of sensing, internal state, reasoning, learning, and action used to implement an intelligent agent. Within Intelligent Agents, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of agent architectures within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of agent architectures, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'agent architectures; Core considerations include the defining characteristics of agent architectures, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000128', 'utility and performance measures', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'utility and performance measures in Artificial Intelligence concerns formal measures used to represent preferences or assess how effectively an agent achieves its specified objectives.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of utility and performance measures within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'Core considerations include the defining characteristics of utility and performance measures, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'utility and performance measures in Artificial Intelligence concerns formal measures used to represent preferences or assess how effectively an agent achieves its specified objectives. Within Intelligent Agents, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of utility and performance measures within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of utility and performance measures, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'utility and performance measures; Core considerations include the defining characteristics of utility and performance measures, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000129', 'state-space formulation', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'state-space formulation in Artificial Intelligence concerns the representation of a problem as states, actions or operators, an initial state, goal conditions, and transition relationships.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of state-space formulation within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'Core considerations include the defining characteristics of state-space formulation, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'state-space formulation in Artificial Intelligence concerns the representation of a problem as states, actions or operators, an initial state, goal conditions, and transition relationships. Within Problem Solving and Search, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of state-space formulation within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of state-space formulation, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'state-space formulation; Core considerations include the defining characteristics of state-space formulation, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000130', 'uninformed search', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'uninformed search in Artificial Intelligence concerns search strategies that use problem structure such as depth, cost, or breadth without heuristic estimates of distance to a goal.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of uninformed search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'Core considerations include the defining characteristics of uninformed search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'uninformed search in Artificial Intelligence concerns search strategies that use problem structure such as depth, cost, or breadth without heuristic estimates of distance to a goal. Within Problem Solving and Search, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of uninformed search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of uninformed search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'uninformed search; Core considerations include the defining characteristics of uninformed search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000131', 'heuristic search', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'heuristic search in Artificial Intelligence concerns search strategies that use an estimate of remaining cost or distance to guide exploration toward promising states.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of heuristic search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'Core considerations include the defining characteristics of heuristic search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'heuristic search in Artificial Intelligence concerns search strategies that use an estimate of remaining cost or distance to guide exploration toward promising states. Within Problem Solving and Search, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of heuristic search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of heuristic search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'heuristic search; Core considerations include the defining characteristics of heuristic search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000132', 'local search', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'local search in Artificial Intelligence concerns iterative optimization or search methods that maintain one or a small number of candidate states and improve them using neighbourhood information.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of local search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'Core considerations include the defining characteristics of local search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'local search in Artificial Intelligence concerns iterative optimization or search methods that maintain one or a small number of candidate states and improve them using neighbourhood information. Within Problem Solving and Search, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of local search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of local search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'local search; Core considerations include the defining characteristics of local search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000133', 'adversarial search', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'adversarial search in Artificial Intelligence concerns search for decision-making in competitive environments where an agent must account for an opposing agent''s actions, typically using minimax-style reasoning.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of adversarial search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'Core considerations include the defining characteristics of adversarial search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'adversarial search in Artificial Intelligence concerns search for decision-making in competitive environments where an agent must account for an opposing agent''s actions, typically using minimax-style reasoning. Within Problem Solving and Search, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of adversarial search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of adversarial search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'adversarial search; Core considerations include the defining characteristics of adversarial search, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000134', 'propositional logic', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'propositional logic in Artificial Intelligence concerns a formal logic in which propositions are represented by Boolean-valued symbols and combined with logical connectives to support deduction.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of propositional logic within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'Core considerations include the defining characteristics of propositional logic, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'propositional logic in Artificial Intelligence concerns a formal logic in which propositions are represented by Boolean-valued symbols and combined with logical connectives to support deduction. Within Knowledge Representation and Reasoning, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of propositional logic within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of propositional logic, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'propositional logic; Core considerations include the defining characteristics of propositional logic, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000135', 'first-order logic', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'first-order logic in Artificial Intelligence concerns a predicate logic that represents objects, properties, and relations using predicates, variables, quantifiers, and logical connectives.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of first-order logic within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'Core considerations include the defining characteristics of first-order logic, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'first-order logic in Artificial Intelligence concerns a predicate logic that represents objects, properties, and relations using predicates, variables, quantifiers, and logical connectives. Within Knowledge Representation and Reasoning, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of first-order logic within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of first-order logic, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'first-order logic; Core considerations include the defining characteristics of first-order logic, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000136', 'ontologies', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'ontologies in Artificial Intelligence concerns formal specifications of concepts, relationships, constraints, and axioms within a domain for shared semantic representation and automated reasoning.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of ontologies within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'Core considerations include the defining characteristics of ontologies, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'ontologies in Artificial Intelligence concerns formal specifications of concepts, relationships, constraints, and axioms within a domain for shared semantic representation and automated reasoning. Within Knowledge Representation and Reasoning, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of ontologies within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of ontologies, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'ontologies; Core considerations include the defining characteristics of ontologies, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000137', 'knowledge graphs', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'knowledge graphs in Artificial Intelligence concerns graph-based representations in which entities and relations are represented as nodes and edges to support semantic integration, querying, and inference.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of knowledge graphs within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'Core considerations include the defining characteristics of knowledge graphs, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'knowledge graphs in Artificial Intelligence concerns graph-based representations in which entities and relations are represented as nodes and edges to support semantic integration, querying, and inference. Within Knowledge Representation and Reasoning, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of knowledge graphs within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of knowledge graphs, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'knowledge graphs; Core considerations include the defining characteristics of knowledge graphs, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Artificial Intelligence', 'Active'), ('KCR_000138', 'inference', 'Engineering & Technology', 'Artificial Intelligence', 'Technical Concept', 'inference in Artificial Intelligence concerns the derivation of conclusions